const ST_SWAN = STAGE(`<circle cx='42' cy='40' r='30' fill='rgba(255,243,207,.18)'/><path d='M14 56 Q14 46 28 44 L42 44 Q34 38 31 28 Q28 16 34 9 Q39 4 44 8 L46 10 L42 11 Q37 12 38 22 Q40 34 50 41 Q66 44 70 54 Q66 62 42 62 Q16 62 14 56Z' fill='#fff'/><path d='M46 10 L53 12.5 L46 14Z' fill='#F0A23A'/><circle cx='41.5' cy='9.6' r='1.2' fill='#13252E'/><path d='M22 50 Q34 44 46 50 Q54 46 62 50' stroke='#E3ECEC' stroke-width='1.6' fill='none'/><path d='M60 20 l1.5 4 l4 1.5 l-4 1.5 l-1.5 4 l-1.5 -4 l-4 -1.5 l4 -1.5Z' fill='#FFF3CF'/>`);
const bubble = { myBg: C.teal, myText: C.ink, myBorder: "1px solid rgba(190,230,225,.5)", charBg: C.white, charText: "#21343A", charBorder: "none", radius: 18, shadow: "none", myAlpha: 100, charAlpha: 100 };
const layout = { bubble: "bubble", avatar: "all", name: false, gap: "normal", time: "show" };

const BG = `${svg(SWAN)} 52px 150px/44px 74px no-repeat,${svg(DUCKLING)} 100px 176px/36px 24px no-repeat,radial-gradient(circle at 74% 166px,#FFFDF2 0,#F6E3B0 19px,rgba(246,227,176,.4) 20.5px,rgba(246,227,176,.12) 55px,transparent 100px),radial-gradient(ellipse 100px 40px at 74% 200px,rgba(246,227,176,.28),transparent),${svg(TREES)} 0 188px/200px 14px repeat-x,${svg(STARS)} 0 40px/220px 170px repeat-x,linear-gradient(180deg,#0B1E2E 0,#2A5560 200px,#1C4C55 201px,#103138 55%,#091E24 100%)`;

const css = `
/* ───── 月湖天鹅 · 第一批 ───── */
[data-wk="chat"]{background:${BG} !important;background-color:${C.deep} !important}
[data-wk="body"]{background:transparent !important;position:relative !important;z-index:1 !important;padding-top:118px !important}
[data-wk="chat"]{position:relative !important}
[data-wk="chat"]::before{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;top:200px !important;bottom:0 !important;background:${svg(RIPPLE)} 0 0/400px 580px repeat !important;pointer-events:none !important;z-index:0 !important}
[data-wk="chat"]::after{content:"" !important;position:absolute !important;left:calc(74% - 160px) !important;width:320px !important;top:201px !important;height:560px !important;background:${svg(GLINT)} 0 0/320px 560px no-repeat !important;-webkit-mask:linear-gradient(180deg,#000 30%,rgba(0,0,0,.4) 75%,transparent) !important;mask:linear-gradient(180deg,#000 30%,rgba(0,0,0,.4) 75%,transparent) !important;filter:blur(.7px) !important;pointer-events:none !important;z-index:0 !important}
[data-wk="chathead"],[data-wk="composer"]{position:relative !important;z-index:2 !important}

/* 顶栏：浮在夜空里的一块深色圆角牌，金色双线框（照参考），名字后面一行金色斜体书名 */
[data-wk="chathead"]{background:rgba(7,25,30,.82) !important;border:1px solid rgba(255,255,255,.28) !important;border-radius:14px !important;margin:6px 10px 0 !important;box-shadow:inset 0 0 0 3px rgba(7,25,30,.82),inset 0 0 0 3.6px rgba(242,178,74,.7),0 6px 18px rgba(0,0,0,.3) !important}
[data-wk="headink"],[data-wk="headink"] *{color:${C.ink} !important}
[data-wk="headname"] [data-wk="headink"]{font-family:Georgia,"Songti SC",serif !important;letter-spacing:.04em !important}
[data-wk="headdim"],[data-wk="headname"] > div:last-child{color:${C.fog} !important}
[data-wk="headname"] > div:last-child::before{content:"The Ugly Duckling · " !important;font:italic 11px/1 Georgia,serif !important;color:${C.gold} !important}
[data-wk="chathead"] [data-wk="headname"]{flex:1 1 auto !important;min-width:110px !important}
[data-wk="chathead"] [data-wk="headname"] > div:last-child{white-space:nowrap !important;overflow:hidden !important;text-overflow:ellipsis !important}
[data-wk="chatback"] svg{stroke:${C.ink} !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:28px !important;min-width:28px !important;height:28px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important;flex-shrink:0 !important}
[data-wk="sameroom"]{background:${svg(I_HOUSE)} center/contain no-repeat !important;margin-left:auto !important}
[data-wk="chatmore"]{background:${svg(I_MORE)} center/contain no-repeat !important;margin-left:6px !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}

/* 头像：圆的，白圈外再一圈金色微光 */
button[data-wk="avatar"],span[data-wk="avatar"],img[data-wk="avatar"],button[data-wk="avatar"] *,span[data-wk="avatar"] *{border-radius:50% !important}
button[data-wk="avatar"],span[data-wk="avatar"]:not([data-halo]),img[data-wk="avatar"]{box-shadow:0 0 0 3px #fff,0 0 0 5.4px #133B42,0 0 0 6.2px rgba(242,178,74,.9),0 0 16px rgba(255,255,255,.3) !important}
/* 顶栏双头像：两颗圆挨着，中间浮着一根小羽毛 */
[data-wk="chathead"] [data-wk="headme"]{display:inline-flex !important;position:relative !important;overflow:visible !important;margin-left:-8px !important;flex-shrink:0 !important}
[data-wk="chathead"] [data-wk="headme"] > *,[data-wk="chathead"] [data-wk="headme"] img,[data-wk="chathead"] img[data-wk="avatar"]{width:32px !important;height:32px !important;min-width:32px !important;flex-shrink:0 !important}
[data-wk="chathead"] [data-wk="headme"]::before{content:"" !important;position:absolute !important;left:-12px !important;bottom:-6px !important;width:16px !important;height:16px !important;z-index:3 !important;background:${svg(I_MORE)} center/contain no-repeat !important}
[data-wk="offline"] [data-wk="chathead"] [data-wk="headme"]{display:none !important}

/* 气泡：浮在水上——他的白、柔光；我的青、半透，顶上一道高光、右下一道水纹。每串最后一条底下一截水里的倒影 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;border-radius:13px !important;font-family:Georgia,"Songti SC",serif !important;letter-spacing:.06em !important;padding:11px 20px !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:linear-gradient(180deg,#FFFFFF,#E6F1F2) !important;color:#0E3138 !important;border:1px solid #fff !important;box-shadow:0 0 16px rgba(255,255,255,.3) !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:linear-gradient(135deg,rgba(143,227,234,.42),rgba(63,162,176,.30) 55%,rgba(155,231,236,.36)),rgba(18,66,75,.92) !important;color:#fff !important;border:1.2px solid rgba(255,255,255,.55) !important;border-top-color:rgba(255,255,255,.95) !important;border-left-color:rgba(255,255,255,.85) !important;box-shadow:none !important}
[data-wk="bubble"][data-kind="text"]::before{content:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::before{content:"" !important;position:absolute !important;left:22px !important;top:4px !important;width:36px !important;height:2px !important;border-radius:2px !important;background:rgba(255,255,255,.45) !important;border:none !important;transform:none !important}
[data-wk="bubble"][data-kind="text"]::after{content:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::after{content:"" !important;position:absolute !important;right:12px !important;bottom:4px !important;left:auto !important;top:auto !important;width:36px !important;height:8px !important;background:${svg(WAVE("rgba(230,245,240,.6)"))} center/contain no-repeat !important;border:none !important;transform:none !important}
[data-last="1"] [data-wk="bubble"][data-kind="text"][data-me="0"]::after,[data-wk="msg"]:not([data-last]) [data-wk="bubble"][data-kind="text"][data-me="0"]::after{content:"" !important;position:absolute !important;left:4px !important;right:4px !important;top:calc(100% + 4px) !important;height:22px !important;border-radius:0 0 18px 18px !important;background:linear-gradient(180deg,rgba(244,246,241,.22),rgba(244,246,241,0)) !important;-webkit-mask:repeating-linear-gradient(180deg,#000 0 3px,transparent 3px 5px) !important;mask:repeating-linear-gradient(180deg,#000 0 3px,transparent 3px 5px) !important;border:none !important;transform:none !important;pointer-events:none !important}
[data-last="1"][data-me="0"],[data-wk="msg"][data-me="0"][data-last="1"]{margin-bottom:14px !important}

/* 时间：不居中——左边一行「今天」小字，下面大一号的钟点，底下一道金线（照参考） */
[data-wk="time"]{text-align:left !important;justify-content:flex-start !important;padding-left:24px !important}
[data-wk="time"] > span{display:inline-block !important;background:transparent !important;border:none !important;border-bottom:1.5px solid ${C.gold} !important;border-radius:0 !important;color:${C.ink} !important;font-family:Georgia,serif !important;font-size:15px !important;letter-spacing:.12em !important;padding:0 18px 6px 0 !important;text-shadow:0 0 8px rgba(255,255,255,.3) !important}

/* 已读：他的前面一只小鸭（白圆点＋橘嘴），我的后面一颗灰圆点 */
[data-wk="meta"]{background:rgba(11,39,45,.9) !important;box-shadow:0 0 8px 4px rgba(11,39,45,.9) !important;border-radius:8px !important;padding:0 4px !important;color:${C.fog} !important;font-size:10.5px !important;letter-spacing:.12em !important;display:inline-flex !important;align-items:center !important;gap:6px !important}
[data-wk="msg"][data-me="0"] [data-wk="meta"]::before{content:"" !important;width:18px !important;height:11px !important;background:${svg(DUCKDOT)} center/contain no-repeat !important;filter:drop-shadow(0 0 3px rgba(255,255,255,.6)) !important}
[data-wk="msg"][data-me="1"] [data-wk="meta"]{flex-direction:row-reverse !important}
[data-wk="msg"][data-me="1"] [data-wk="meta"]::before{content:"" !important;width:7px !important;height:7px !important;border-radius:50% !important;background:${C.fog} !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-run][data-last="1"] + [data-wk="cardmeta"]{display:block !important;font-size:10.5px !important;color:${C.fog} !important;padding:2px 0 0 62px !important}
[data-run][data-last="1"] + [data-wk="cardmeta"][data-me="1"]{text-align:right !important;padding:2px 62px 0 0 !important}
[data-wk="bubble"][data-kind="typing"]{background:${C.white} !important;border:none !important;border-radius:18px !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:${C.teal} !important}

/* 动描：不进气泡——像湖面上一行被月光照着的字：不带框，两边各一道细水纹，淡金斜体 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"]{display:block !important;background:${svg(WAVE("rgba(226,167,60,.6)"))} left center/30px 8px no-repeat,${svg(WAVE("rgba(226,167,60,.6)"))} right center/30px 8px no-repeat !important;border:none !important;border-radius:0 !important;box-shadow:none !important;color:#E8D7AE !important;opacity:1 !important;font-family:Georgia,"Songti SC",serif !important;font-style:italic !important;font-size:13px !important;line-height:1.85 !important;padding:6px 40px !important;text-align:center !important;text-shadow:0 0 8px rgba(0,0,0,.5) !important}
/* 系统提示：一行小字，前面一颗小星 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:${C.fog} !important;font-size:11px !important;font-style:normal !important;letter-spacing:.1em !important}
[data-wk="sysnotetext"]::before{content:"✧ " !important;color:${C.gold} !important}

/* 底栏：同顶栏一块深色圆角牌，金色双线；加号是一颗裂开的蛋，回复是一片睡莲叶，发送是小鸭的脑袋＋橘色小嘴 */
[data-wk="composer"]{background:rgba(7,25,30,.82) !important;border:1px solid rgba(255,255,255,.28) !important;border-radius:14px !important;margin:0 10px 8px !important;box-shadow:inset 0 0 0 3px rgba(7,25,30,.82),inset 0 0 0 3.6px rgba(242,178,74,.7) !important;align-items:center !important;gap:8px !important}
[data-wk="chatinput"]{background:linear-gradient(180deg,#24525A,#1A3F46) !important;border:1px solid rgba(190,230,225,.4) !important;border-radius:16px !important;color:${C.ink} !important}
[data-wk="chatinput"]::placeholder{color:${C.fog} !important}
[data-wk="chatplus"]{width:28px !important;min-width:28px !important;height:32px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:${svg(I_PLUS)} center/contain no-repeat !important;transform:none !important;rotate:none !important}
[data-wk="send"]{width:52px !important;min-width:52px !important;height:36px !important;border:none !important;border-radius:0 !important;box-shadow:none !important;background:${svg(I_SEND)} center/contain no-repeat !important;opacity:1 !important;filter:drop-shadow(0 0 6px rgba(255,255,255,.35)) !important}
[data-wk="chatreply"]{width:38px !important;min-width:38px !important;height:32px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:${svg(I_REPLY)} center/contain no-repeat !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.92) !important}
/* ───── 更丑小鸭：他是灰小鸭、我是白天鹅 ───── */
/* 头像：他一圈灰绒毛（毛茸茸的软边），我一圈白羽，右上插一根小白羽毛 */
[data-wk="msg"][data-me="0"] [data-wk="avatar"],[data-wk="cardrow"][data-me="0"] [data-wk="avatar"],[data-wk="chathead"] > button img[data-wk="avatar"],[data-wk="chathead"] > button > [data-wk="avatar"]{box-shadow:0 0 0 3px #B4BDBF,0 0 0 4px #D6DCDD,0 0 5px 5px rgba(168,177,179,.55) !important}
/* 顶栏双头像中间：一只灰小鸭和一只白天鹅面对面 */
[data-wk="chathead"] [data-wk="headme"]::before{left:-22px !important;bottom:-8px !important;width:40px !important;height:20px !important;background:${svg(PAIR)} center/contain no-repeat !important;filter:drop-shadow(0 0 3px rgba(0,0,0,.5)) !important}
/* 气泡：我的高光挪进底色；每串第一条——他的角上一撮灰绒毛，我的角上一根白羽 */
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:linear-gradient(rgba(255,255,255,.5),rgba(255,255,255,.5)) 22px 4px/36px 1.4px no-repeat,linear-gradient(135deg,rgba(143,227,234,.42),rgba(63,162,176,.30) 55%,rgba(155,231,236,.36)),rgba(18,66,75,.92) !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::before{content:none !important}
[data-first="1"] [data-wk="bubble"][data-kind="text"]::before,[data-wk="msg"]:not([data-first]) [data-wk="bubble"][data-kind="text"]::before{content:"" !important;position:absolute !important;top:-11px !important;width:20px !important;height:20px !important;border:none !important;background-color:transparent !important;transform:none !important;z-index:2 !important}
[data-first="1"] [data-wk="bubble"][data-kind="text"][data-me="0"]::before{left:-4px !important;right:auto !important;background:${svg(FLUFF)} center/contain no-repeat !important}
[data-first="1"] [data-wk="bubble"][data-kind="text"][data-me="1"]::before{right:-6px !important;left:auto !important;background:${svg(PLUME)} center/contain no-repeat !important;filter:drop-shadow(0 0 3px rgba(255,255,255,.6)) !important}
/* 已读：一对小鸭掌印——他的橘色、我的白色 */
[data-wk="msg"][data-me="0"] [data-wk="meta"]::before{content:"" !important;width:20px !important;height:12px !important;background:${svg(PRINT("#F0A23A"))} center/contain no-repeat !important;filter:none !important;border-radius:0 !important}
[data-wk="msg"][data-me="1"] [data-wk="meta"]::before{content:"" !important;width:20px !important;height:12px !important;background:${svg(PRINT("#FFFFFF"))} center/contain no-repeat !important;border-radius:0 !important;opacity:.85 !important}

/* ───── 月湖天鹅 · 第二批：卡片（形状不动；他的白瓷、我的水色玻璃，同气泡；细金线收边） ───── */
[data-wk="transfercard"],[data-wk="photocard"],[data-wk="wxcard"],[data-wk="geocard"] > [data-wk="card"],[data-wk="namecard"],[data-part="offlog"],[data-wk="callpill"] > [data-wk="block"],[data-wk="rpcard"]{position:relative !important;overflow:visible !important;background:linear-gradient(180deg,#FFFFFF,#E6F1F2) !important;border:1px solid #fff !important;border-radius:14px !important;box-shadow:0 0 16px rgba(255,255,255,.28),inset 0 0 0 4px #F7FAF9,inset 0 0 0 4.6px rgba(242,178,74,.55) !important;color:#0E3138 !important}
[data-wk="transfercard"] *,[data-wk="namecard"] *,[data-part="offlog"] *,[data-wk="geocard"] *,[data-wk="callpill"] *,[data-wk="photocard"] *{color:#0E3138 !important;border-color:rgba(14,49,56,.15) !important}
/* 转账：白瓷卡，金额金色衬线；收下盖一枚金色羽毛圆章 */
[data-wk="transferamount"],[data-wk="transfercur"]{color:#C98A1E !important;font-family:Georgia,serif !important}
[data-wk="transferrule"]{border:none !important;height:1px !important;background:linear-gradient(90deg,transparent,#F2B24A,transparent) !important}
[data-wk="transfernotch"]{display:none !important}
[data-wk="transferfoot"]{background:rgba(18,66,75,.06) !important;border-top:1px solid rgba(14,49,56,.12) !important}
[data-wk="transferbtn"]{border-radius:12px !important}
[data-wk="transferbtn"][data-part="take"]{background:#12424B !important;color:#fff !important;border:1px solid #fff !important}
[data-wk="transferbtn"][data-part="back"]{background:transparent !important;border:1px solid rgba(14,49,56,.3) !important}
[data-wk="transferseal"]{background:${svg(FEATHER)} center/contain no-repeat !important;border:none !important;box-shadow:none !important;width:44px !important;height:44px !important;font-size:0 !important;color:transparent !important}
[data-wk="transferseal"] *{opacity:0 !important}
[data-wk="transfercard"][data-status="accepted"] [data-wk="transferseal"]{transform:rotate(-10deg) !important}
[data-wk="transfercard"][data-status="returned"]{opacity:.55 !important}
/* 红包：不是信封——一块水色玻璃，左边卧着一颗金蛋（丑小鸭的蛋）；领完蛋壳裂开变淡 */
[data-wk="rpcard"]{background:linear-gradient(135deg,rgba(143,227,234,.42),rgba(63,162,176,.30) 55%,rgba(155,231,236,.36)),rgba(18,66,75,.95) !important;border:1.2px solid rgba(255,255,255,.6) !important;border-top-color:rgba(255,255,255,.95) !important;padding-left:58px !important;box-shadow:inset 0 0 0 4px #2A6670,inset 0 0 0 4.6px rgba(242,178,74,.6) !important}
[data-wk="rpcard"]::before{content:"" !important;position:absolute !important;left:12px !important;top:calc(50% - 22px) !important;width:38px !important;height:44px !important;background:${svg(EGG)} center/contain no-repeat !important;filter:drop-shadow(0 0 8px rgba(246,210,122,.6)) !important;z-index:2 !important}
[data-wk="rpcard"] *{color:#fff !important}
[data-wk="rpflap"],[data-wk="rpseal"],[data-wk="rpcorner"]{display:none !important}
[data-wk="rpcard"][data-status="done"]{opacity:.6 !important}
[data-wk="rpcard"][data-status="done"]::before{filter:grayscale(.6) !important}
[data-wk="rpenvelope"]{background:radial-gradient(circle at 70% 18%,#FFFDF2 0 18px,rgba(246,227,176,.3) 20px,transparent 70px),linear-gradient(180deg,#0B1E2E,#2A5560 45%,#1C4C55 46%,#091E24) !important;border:1px solid rgba(255,255,255,.4) !important;border-radius:18px !important;box-shadow:inset 0 0 0 4px #10283A,inset 0 0 0 4.6px rgba(242,178,74,.7),0 10px 30px rgba(0,0,0,.5) !important}
[data-wk="rpenvelope"] [data-wk="rparc"]{background:transparent !important;border:none !important}
[data-wk="rpenvelope"] *{color:#fff !important}
[data-wk="rpopenbtn"]{background:${svg(EGG)} center/contain no-repeat !important;border:none !important;box-shadow:none !important;filter:drop-shadow(0 0 12px rgba(246,210,122,.7)) !important}
[data-wk="rpopenbtn"] *{opacity:0 !important}
[data-wk="rpamount"]{color:#FFF3CF !important;font-family:Georgia,serif !important;text-shadow:0 0 10px rgba(246,227,176,.6) !important}
/* 照片：白瓷框里一块湖色小屏；语音：水色玻璃条，波形是奶油色 */
[data-wk="photocard"]{padding:8px 8px 10px !important}
[data-wk="photoface"]{border-radius:10px !important;background:linear-gradient(180deg,#1C4C55,#103138) !important;border:none !important}
[data-wk="photoface"] *,[data-wk="photohint"]{color:#E8F1F0 !important}
[data-wk="photoface"] svg{stroke:#FFF3CF !important}
[data-wk="voice"][data-me]{background:linear-gradient(180deg,#FFFFFF,#E6F1F2) !important;border:1px solid #fff !important;border-radius:13px !important;box-shadow:0 0 14px rgba(255,255,255,.28) !important}
[data-wk="voice"][data-me="1"]{background:linear-gradient(135deg,rgba(143,227,234,.42),rgba(63,162,176,.30)),rgba(18,66,75,.92) !important;border-color:rgba(255,255,255,.6) !important;box-shadow:none !important}
[data-wk="voice"] > *{background:transparent !important;border:none !important;box-shadow:none !important;color:#0E3138 !important}
[data-wk="voice"][data-me="1"] > *{color:#fff !important}
[data-wk="voicewave"] span{background:#3FA2B0 !important}
[data-wk="voice"][data-me="1"] [data-wk="voicewave"] span{background:#FFF3CF !important}
/* 天气、位置、名片 */
[data-wk="wxcard"]{background:linear-gradient(180deg,#0B1E2E,#1C4C55) !important;border:1px solid rgba(255,255,255,.4) !important;box-shadow:inset 0 0 0 4px #10283A,inset 0 0 0 4.6px rgba(242,178,74,.6) !important}
[data-wk="wxcard"] *{color:#fff !important}
[data-wk="wxcardsky"]{background:transparent !important}
[data-wk="wxcardsky"] > div:first-child{background:radial-gradient(circle,#FFFDF2 0 12px,rgba(246,227,176,.35) 14px,transparent 60%) !important}
[data-wk="wxcardsky"] svg{stroke:#FFF3CF !important}
[data-wk="wxcardsky"] span[style*="999"],[data-wk="wxcardrain"]{background:rgba(255,255,255,.1) !important;border:1px solid rgba(255,255,255,.35) !important}
[data-wk="wxcardtemp"]{font-family:Georgia,serif !important}
[data-wk="wxcardsay"]{background:linear-gradient(180deg,#FFFFFF,#E6F1F2) !important;border-top:none !important;border-radius:0 0 13px 13px !important}
[data-wk="wxcardsay"],[data-wk="wxcardsay"] *{color:#0E3138 !important}
[data-wk="geopin"]{background:#F2B24A !important;box-shadow:0 0 0 2px #fff,0 0 10px #F2B24A !important}
[data-wk="geopinstem"]{background:#fff !important}
[data-wk="namecard"] img{border-radius:50% !important;box-shadow:0 0 0 2.5px #fff,0 0 0 3.4px #F2B24A !important}
/* 拍一拍、通话结束：一行奶油色小字，两头各一道细水纹 */
[data-wk="note"][data-part="pat"],[data-wk="note"][data-part="call"]{display:inline-block !important;border:none !important;color:#FFF3CF !important;font-family:Georgia,"Songti SC",serif !important;padding:2px 36px !important;font-size:12px !important;background:${svg(WAVE("rgba(255,243,207,.7)"))} left center/28px 7px no-repeat,${svg(WAVE("rgba(255,243,207,.7)"))} right center/28px 7px no-repeat,rgba(11,39,45,.85) !important;border-radius:12px !important}
[data-wk="note"][data-part="call"] svg{stroke:#FFF3CF !important}
[data-wk="note"][data-part="callsum"]{color:${C.fog} !important}
/* 线下小结 */
[data-wk="offlogtitle"]{font-family:Georgia,serif !important;font-style:italic !important;letter-spacing:.15em !important;color:#C98A1E !important}
[data-wk="offlogopen"],[data-wk="offlogredo"],[data-wk="offlogundo"],[data-wk="offlogrestore"]{color:#2D6B70 !important}
[data-wk="offlogtranscript"]{border-top:1px solid rgba(14,49,56,.15) !important}
/* 加号面板：一片片圆圆的睡莲叶——白瓷和水色交替 */
[data-wk="chatpanel"]{background:rgba(7,25,30,.92) !important;border-top:1px solid rgba(255,255,255,.2) !important}
[data-wk="chattoolicon"]{background:linear-gradient(180deg,#FFFFFF,#E6F1F2) !important;border:1px solid #fff !important;border-radius:50% !important;box-shadow:0 0 12px rgba(255,255,255,.25),inset 0 0 0 3px #F3F8F8,inset 0 0 0 3.6px rgba(242,178,74,.6) !important}
[data-wk="chattoolglyph"],[data-wk="chattoolglyph"] svg{stroke:#0E3138 !important;color:#0E3138 !important}
[data-wk="chattool"]:nth-child(odd) [data-wk="chattoolicon"]{background:linear-gradient(135deg,rgba(143,227,234,.42),rgba(63,162,176,.30)),rgba(18,66,75,.95) !important;border-color:rgba(255,255,255,.6) !important;box-shadow:inset 0 0 0 3px #2A6670,inset 0 0 0 3.6px rgba(242,178,74,.6) !important}
[data-wk="chattool"]:nth-child(odd) [data-wk="chattoolglyph"],[data-wk="chattool"]:nth-child(odd) [data-wk="chattoolglyph"] svg{stroke:#fff !important;color:#fff !important}
[data-wk="chattoollabel"]{color:#CFE6EA !important}
/* 引用三处：左边一道奶油色细线 */
[data-wk="quotedraft"]{background:rgba(7,25,30,.92) !important;border-top:none !important}
[data-wk="quote"]{background:rgba(11,39,45,.85) !important;color:#CFE6EA !important;border:none !important;border-left:2px solid #FFF3CF !important;border-radius:6px !important;opacity:1 !important}
[data-wk="quoteicon"],[data-wk="quoteclear"]{color:#F2B24A !important}
[data-wk="bubble"] [data-wk="quotetext"]{display:block !important;border-left:2px solid currentColor !important;padding-left:8px !important;opacity:.7 !important}
/* 线下：提示键是那颗裂开的蛋，照片键是一幅小小的月夜湖 */
[data-wk="offline"] [data-wk="chathead"] button[title="给 Ta 一个提示"]{width:24px !important;min-width:24px !important;height:28px !important;background:${svg(I_PLUS)} center/contain no-repeat !important;border:none !important;box-shadow:none !important;flex-shrink:0 !important}
[data-wk="offline"] [data-wk="chathead"] button[title="给 Ta 一个提示"] *{opacity:0 !important}
[data-wk="offcomposer"] button[title="给 Ta 看真实照片"]{width:30px !important;min-width:30px !important;height:30px !important;border:none !important;box-shadow:none !important;font-size:0 !important;background:${svg(I_PIC)} center/contain no-repeat !important}
[data-wk="offcomposer"] button[title="给 Ta 看真实照片"] *{opacity:0 !important}
/* ───── 月湖天鹅 · 第三批：状态卡是一扇月夜湖窗——深色湖底、白瓷小卡、细金线；好感是丑小鸭长大 ───── */
[data-wk="statecard"]{background:radial-gradient(circle at 80% 0%,rgba(246,227,176,.22),transparent 45%),linear-gradient(180deg,#0B1E2E,#1C4C55 40%,#0C2A30) !important;border:1px solid rgba(255,255,255,.3) !important;border-radius:18px !important;box-shadow:inset 0 0 0 4px #10283A,inset 0 0 0 4.6px rgba(242,178,74,.6),0 14px 34px rgba(0,0,0,.5) !important;color:#fff !important}
[data-wk="statehead"]{background:transparent !important;border-bottom:1px solid rgba(255,255,255,.15) !important}
[data-wk="statehead"] *{color:#fff !important}
[data-wk="statehead"] [data-wk="avatar"]{border-radius:50% !important;box-shadow:0 0 0 3px #B4BDBF,0 0 5px 4px rgba(168,177,179,.5) !important}
[data-wk="statehead"] button{border:1px solid rgba(255,255,255,.4) !important;border-radius:50% !important;background:rgba(7,25,30,.6) !important}
[data-wk="statemood"]{display:inline-block !important;background:transparent !important;border:1px solid #F2B24A !important;color:#FFF3CF !important;padding:0 10px !important;margin-right:4px !important;border-radius:10px !important;font-family:Georgia,"Songti SC",serif !important}
[data-wk="statecard"] div:has(> button[aria-pressed]){background:rgba(7,25,30,.6) !important;border:1px solid rgba(255,255,255,.2) !important;border-radius:14px !important;padding:3px !important;margin:12px 16px !important}
[data-wk="statecard"] button[aria-pressed]{color:#93AFAE !important;border:none !important;border-radius:11px !important;background:transparent !important;font-family:Georgia,"Songti SC",serif !important}
[data-wk="statecard"] button[aria-pressed="true"]{background:linear-gradient(180deg,#FFFFFF,#E6F1F2) !important;color:#0E3138 !important}
[data-wk="stateseen"],[data-wk="statevoice"]{position:relative !important;overflow:visible !important;background:linear-gradient(180deg,#FFFFFF,#E6F1F2) !important;border:1px solid #fff !important;border-radius:14px !important;margin:16px 16px 12px !important;color:#0E3138 !important;box-shadow:0 0 14px rgba(255,255,255,.2),inset 0 0 0 4px #F7FAF9,inset 0 0 0 4.6px rgba(242,178,74,.55) !important}
[data-wk="statevoice"]{background:linear-gradient(135deg,rgba(143,227,234,.42),rgba(63,162,176,.30)),rgba(18,66,75,.95) !important;border-color:rgba(255,255,255,.6) !important;color:#fff !important;box-shadow:inset 0 0 0 4px #2A6670,inset 0 0 0 4.6px rgba(242,178,74,.6) !important}
[data-wk="stateseen"]::before{content:"" !important;position:absolute !important;left:10px !important;top:-10px !important;width:20px !important;height:20px !important;background:${svg(FLUFF)} center/contain no-repeat !important}
[data-wk="statevoice"]::before{content:"" !important;position:absolute !important;right:10px !important;top:-10px !important;width:20px !important;height:20px !important;background:${svg(PLUME)} center/contain no-repeat !important}
[data-wk="stateseen"] *{color:#0E3138 !important}
[data-wk="statevoice"] *{color:#fff !important}
[data-wk="stateseen"] > span[aria-hidden],[data-wk="statevoice"] > span[aria-hidden]{display:none !important}
[data-wk="statewear"]{background:rgba(18,66,75,.06) !important;border:1px solid rgba(14,49,56,.2) !important;border-radius:10px !important}
[data-wk="statewear"] > span{background:transparent !important;border:1px solid rgba(14,49,56,.2) !important;border-radius:8px !important}
[data-wk="statevoicedel"],[data-wk="statevoiceclear"]{color:#F2B24A !important}
[data-wk="statevoice"] + div > button{background:rgba(7,25,30,.6) !important;color:#fff !important;border:1px solid rgba(255,255,255,.4) !important;border-radius:12px !important}
/* 好感：不做进度条——丑小鸭长大：蛋（<20）→ 灰毛小鸭（20–49）→ 半大的鸭（50–79）→ 白天鹅（80+）。
   用的是心那几层：形状变量换成整块方形，四层各放一张图，按 --sc-heart-lvl 只亮一张 */
[data-wk="stateaff"]{background:rgba(7,25,30,.55) !important;border-top:1px solid rgba(255,255,255,.15) !important;position:relative !important;display:block !important;padding:16px 120px 18px 20px !important;min-height:112px !important}
[data-wk="stateaff"] *{color:#fff !important}
[data-wk="stateheart"]{position:absolute !important;right:18px !important;left:auto !important;top:50% !important;margin-top:-40px !important;width:92px !important;height:84px !important;--sc-heart-mask:${svg(`<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 10 10'><rect width='10' height='10'/></svg>`)} !important}
[data-wk="stateheart"] > div,[data-wk="stateheartknob"]{inset:0 !important;-webkit-mask-size:100% 100% !important;mask-size:100% 100% !important;background-color:transparent !important;border:none !important}
[data-wk="stateheart"] > div:not([data-wk]){display:none !important}
[data-wk="stateheartfill"] > div{display:none !important}
[data-wk="stateheartline"]{background:${svg(ST_EGG)} center/contain no-repeat !important;opacity:calc(1 - clamp(0,(var(--sc-heart-lvl) - 0.195)*1000,1)) !important}
[data-wk="stateheartbase"]{background:${svg(ST_DUCK)} center/contain no-repeat !important;opacity:calc(clamp(0,(var(--sc-heart-lvl) - 0.195)*1000,1) - clamp(0,(var(--sc-heart-lvl) - 0.495)*1000,1)) !important}
[data-wk="stateheartfill"]{background:${svg(ST_TEEN)} center/contain no-repeat !important;opacity:calc(clamp(0,(var(--sc-heart-lvl) - 0.495)*1000,1) - clamp(0,(var(--sc-heart-lvl) - 0.795)*1000,1)) !important}
[data-wk="stateheartknob"]{display:block !important;position:absolute !important;left:0 !important;bottom:0 !important;width:100% !important;height:100% !important;margin:0 !important;transform:none !important;background:${svg(ST_SWAN)} center/contain no-repeat !important;opacity:calc(clamp(0,(var(--sc-heart-lvl) - 0.795)*1000,1)) !important;filter:drop-shadow(0 0 8px rgba(255,243,207,.5)) !important}
[data-wk="stateheartnum"]{position:absolute !important;inset:auto 0 -6px 0 !important;display:flex !important;justify-content:center !important;padding:0 !important;font:600 13px/1 Georgia,serif !important;color:#FFF3CF !important;-webkit-text-stroke:0 !important;text-shadow:0 0 4px #000 !important;z-index:3 !important}
[data-wk="stateaffval"]{display:none !important}

/* 翻旧的：一张张白瓷小卡，左上一根小羽毛写着第几张 */
[data-wk="statehistbtn"]{background:rgba(7,25,30,.6) !important;color:#fff !important;border:1px solid rgba(255,255,255,.4) !important;border-radius:12px !important}
[data-wk="statehistbtn"][data-part="back"]{display:inline-block !important;width:auto !important;padding:4px 16px !important}
[data-wk="statehisthead"] > :first-child{color:#fff !important;font-family:Georgia,"Songti SC",serif !important}
[data-wk="statehisthead"] [data-wk="statevoiceclear"]{border:1px solid #F2B24A !important;border-radius:10px !important;background:transparent !important}
[data-wk="statehistlist"]{counter-reset:pg !important}
[data-wk="statehistitem"]{counter-increment:pg !important;position:relative !important;background:linear-gradient(180deg,#FFFFFF,#E6F1F2) !important;border:1px solid #fff !important;border-radius:14px !important;padding:26px 18px 14px !important;margin:18px 0 12px !important;box-shadow:inset 0 0 0 4px #F7FAF9,inset 0 0 0 4.6px rgba(242,178,74,.55) !important}
[data-wk="statehistitem"]:nth-child(even){background:linear-gradient(135deg,rgba(143,227,234,.42),rgba(63,162,176,.30)),rgba(18,66,75,.95) !important;border-color:rgba(255,255,255,.6) !important;box-shadow:inset 0 0 0 4px #2A6670,inset 0 0 0 4.6px rgba(242,178,74,.6) !important}
[data-wk="statehistitem"] *{color:#0E3138 !important}
[data-wk="statehistitem"]:nth-child(even) *{color:#fff !important}
[data-wk="statehistitem"]::before{content:"No." counter(pg) !important;position:absolute !important;left:14px !important;top:8px !important;font:italic 11px/1 Georgia,serif !important;color:#C98A1E !important;letter-spacing:.1em !important}
[data-wk="statehistmood"]{background:transparent !important;border:1px solid #F2B24A !important;border-radius:8px !important;padding:0 6px !important}
[data-wk="statehisttime"]{opacity:.6 !important}
[data-wk="statehisttext"]{font-family:Georgia,"Songti SC",serif !important}
[data-wk="statehistmeta"]{background:rgba(14,49,56,.06) !important;border-radius:8px !important}
[data-wk="statehistend"]{color:#93AFAE !important;letter-spacing:.3em !important}

/* Ta 眼里：贴条换成一根小白羽毛 */
[data-wk="gazepage"]{background:linear-gradient(180deg,#0B1E2E,#1C4C55 30%,#091E24) !important}
[data-wk="gazetitle"]{color:#fff !important;font-family:Georgia,"Songti SC",serif !important}
[data-wk="gazetab"]{background:rgba(7,25,30,.6) !important;color:#93AFAE !important;border:1px solid rgba(255,255,255,.2) !important;border-radius:12px !important;clip-path:none !important}
[data-wk="gazetab"][data-on="1"]{background:linear-gradient(180deg,#FFFFFF,#E6F1F2) !important;color:#0E3138 !important}
[data-wk="gazetab"] *{clip-path:none !important}
[data-wk="gazestatus"]{color:#93AFAE !important}
[data-wk="gazecard"]{position:relative !important;overflow:visible !important;background:linear-gradient(180deg,#FFFFFF,#E6F1F2) !important;border:1px solid #fff !important;border-radius:14px !important;box-shadow:0 0 14px rgba(255,255,255,.18) !important}
[data-wk="gazetape"]{background:${svg(PLUME)} center/contain no-repeat !important;width:24px !important;height:24px !important;box-shadow:none !important;border:none !important;filter:drop-shadow(0 1px 2px rgba(0,0,0,.3)) !important}
[data-wk="gazecardname"]{color:#0E3138 !important;font-family:Georgia,"Songti SC",serif !important}
[data-wk="gazecardtext"],[data-wk="gazecardtime"]{color:#4E6A6E !important}
[data-wk="gazeletter"],[data-wk="gazehistory"]{background:linear-gradient(180deg,#FFFFFF,#E6F1F2) !important;color:#0E3138 !important;border:1px solid #fff !important;border-radius:16px !important;box-shadow:inset 0 0 0 4px #F7FAF9,inset 0 0 0 4.6px rgba(242,178,74,.55) !important}
[data-wk="gazeletter"] *,[data-wk="gazehistory"] *{color:#0E3138 !important}
[data-wk="gazeempty"]{background:rgba(7,25,30,.6) !important;color:#fff !important;border:1px solid rgba(255,255,255,.3) !important;border-radius:14px !important}
[data-wk="gazeempty"] *{color:#fff !important}
[data-wk="gazeempty"] button{background:linear-gradient(180deg,#FFFFFF,#E6F1F2) !important;color:#0E3138 !important;border:none !important;border-radius:12px !important}

/* ───── 线下：同一片月夜湖；他一张白瓷卡、我一块水色玻璃，左上角绒毛/羽毛；说的话奶油色高亮，心里话淡金斜体 ───── */
[data-wk="offline"]:not([style*="url("]){background:${BG} !important;background-color:#0C2A30 !important}
[data-wk="offline"] [data-wk="offbody"]{background:transparent !important}
[data-wk="offline"] [data-wk="chathead"]{background:rgba(7,25,30,.82) !important;border:1px solid rgba(255,255,255,.28) !important;border-radius:14px !important;margin:6px 10px 0 !important;box-shadow:inset 0 0 0 3px rgba(7,25,30,.82),inset 0 0 0 3.6px rgba(242,178,74,.7) !important}
[data-wk="offline"] [data-wk="chathead"] *{white-space:nowrap !important}
[data-wk="offline"] [data-wk="headname"] > div:last-child{white-space:normal !important;line-height:1.35 !important;color:#93AFAE !important}
[data-wk="offline"] [data-wk="headname"] > div:last-child::before{content:none !important}
[data-wk="offline"] [data-wk="offtitle"],[data-wk="offline"] [data-wk="offtitle"] *,[data-wk="offline"] [data-wk="chatback"] *{color:#fff !important}
[data-wk="offline"] [data-wk="chatback"] svg{stroke:#fff !important}
[data-wk="offline"] [data-wk="chathead"] button:last-child:not([data-wk]){background:transparent !important;color:#FFF3CF !important;border:1px solid #F2B24A !important;border-radius:12px !important;font-size:12px !important;padding:3px 10px !important;flex-shrink:0 !important}
[data-wk="offline"] [data-wk="chatmore"]{width:26px !important;min-width:26px !important;height:26px !important}
[data-wk="offcomposer"]{background:rgba(7,25,30,.82) !important;border:1px solid rgba(255,255,255,.28) !important;border-radius:14px !important;margin:0 10px 8px !important;box-shadow:inset 0 0 0 3px rgba(7,25,30,.82),inset 0 0 0 3.6px rgba(242,178,74,.7) !important}
[data-wk="offcomposer"] textarea{background:linear-gradient(180deg,#24525A,#1A3F46) !important;border:1px solid rgba(190,230,225,.4) !important;border-radius:14px !important;color:#fff !important}
[data-wk="offcomposer"] button:not([title]):not([data-wk]){width:52px !important;min-width:52px !important;height:36px !important;background:${svg(I_SEND)} center/contain no-repeat !important;border:none !important;box-shadow:none !important;border-radius:0 !important}
[data-wk="offcomposer"] button:not([title]):not([data-wk]) *{opacity:0 !important}
[data-wk="offcomposer"] button[title="让 Ta 演绎"]{width:38px !important;min-width:38px !important;height:32px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:${svg(I_REPLY)} center/contain no-repeat !important;font-size:0 !important}
[data-wk="offcomposer"] button[title="让 Ta 演绎"] *{opacity:0 !important}
[data-wk="offcard"]{position:relative !important;overflow:visible !important;background:linear-gradient(180deg,#FFFFFF,#E6F1F2) !important;border:1px solid #fff !important;border-radius:16px !important;box-shadow:0 0 16px rgba(255,255,255,.2),inset 0 0 0 4px #F7FAF9,inset 0 0 0 4.6px rgba(242,178,74,.5) !important}
[data-wk="offcard"][data-me="1"]{background:linear-gradient(135deg,rgba(143,227,234,.42),rgba(63,162,176,.30) 55%,rgba(155,231,236,.36)),rgba(18,66,75,.95) !important;border-color:rgba(255,255,255,.6) !important;box-shadow:inset 0 0 0 4px #2A6670,inset 0 0 0 4.6px rgba(242,178,74,.6) !important}
[data-wk="offcard"]::before{content:"" !important;position:absolute !important;left:10px !important;top:-10px !important;width:20px !important;height:20px !important;background:${svg(FLUFF)} center/contain no-repeat !important}
[data-wk="offcard"][data-me="1"]::before{left:auto !important;right:10px !important;background:${svg(PLUME)} center/contain no-repeat !important}
[data-wk="offhead"] img,[data-wk="offhead"] [data-wk="avatar"]{border-radius:50% !important;box-shadow:0 0 0 2.5px #B4BDBF !important}
[data-wk="offcard"][data-me="1"] [data-wk="offhead"] img,[data-wk="offcard"][data-me="1"] [data-wk="offhead"] [data-wk="avatar"]{box-shadow:0 0 0 2.5px #fff,0 0 0 3.4px #F2B24A !important}
[data-wk="offname"]{color:#C98A1E !important;font-family:Georgia,"Songti SC",serif !important;font-style:italic !important}
[data-wk="offcard"][data-me="1"] [data-wk="offname"]{color:#FFF3CF !important}
[data-wk="offtext"]{color:#24414A !important;font-family:Georgia,"Songti SC",serif !important}
[data-wk="offcard"][data-me="1"] [data-wk="offtext"]{color:#E8F1F0 !important}
[data-wk="offsay"]{color:#0E3138 !important;background:linear-gradient(transparent 60%,rgba(242,178,74,.35) 60%) !important;border:none !important;font-weight:600 !important;box-decoration-break:clone !important;-webkit-box-decoration-break:clone !important}
[data-wk="offcard"][data-me="1"] [data-wk="offsay"]{color:#fff !important;background:linear-gradient(transparent 60%,rgba(255,243,207,.3) 60%) !important}
[data-wk="offthought"]{background:transparent !important;border:none !important;color:#9C7A3E !important;font-style:italic !important}
[data-wk="offcard"][data-me="1"] [data-wk="offthought"]{color:#E8D7AE !important}
[data-wk="offcardacts"] svg{stroke:#6E8A8E !important;color:#6E8A8E !important}
[data-wk="offreplyopt"]{background:linear-gradient(180deg,#FFFFFF,#E6F1F2) !important;border:1px solid #fff !important;border-radius:12px !important;color:#0E3138 !important}

/* ───── 通话：他白瓷、我水色玻璃；头像外一圈细金线和月光 ───── */
[data-wk="callbubble"]{background:linear-gradient(180deg,#FFFFFF,#E6F1F2) !important;color:#0E3138 !important;border:1px solid #fff !important;border-radius:13px !important;box-shadow:0 0 14px rgba(255,255,255,.25) !important}
[data-wk="callmsg"][data-me="1"] [data-wk="callbubble"]{background:linear-gradient(135deg,rgba(143,227,234,.42),rgba(63,162,176,.30)),rgba(18,66,75,.95) !important;color:#fff !important;border-color:rgba(255,255,255,.6) !important;box-shadow:none !important}
[data-wk="callbubble"]::before,[data-wk="callbubble"]::after{content:none !important}
[data-wk="callavatar"]{border-radius:50% !important;box-shadow:0 0 0 3px #fff,0 0 0 8px #133B42,0 0 0 9px rgba(242,178,74,.9),0 0 40px 10px rgba(246,227,176,.35) !important}

/* 打电话那一屏（语音）：整屏底色跟这套走；三个按键换成这套的扣子，中间挂断单独一色 */
[data-wk="call"][data-video="0"]{background:radial-gradient(circle at 70% 18%,#FFFDF2 0 18px,rgba(246,227,176,.3) 20px,transparent 80px),linear-gradient(180deg,#0B1E2E,#1C4C55 50%,#091E24) !important}
[data-wk="call"][data-video="0"] [data-wk="calltitle"]{color:#fff !important}
[data-wk="call"][data-video="0"] [data-wk="callhead"] > div:not([data-wk]){color:rgba(255,255,255,.65) !important}
[data-wk="call"][data-video="0"] > button:first-child{background:rgba(255,255,255,.12) !important}
[data-wk="call"][data-video="0"] > button:first-child svg{stroke:#fff !important}
[data-wk="callbtns"] button > span:first-child{background:linear-gradient(180deg,#FFFFFF,#E6F1F2) !important;border-radius:50% !important;box-shadow:0 0 0 1px #fff,0 0 0 5px #133B42,0 0 0 5.6px rgba(242,178,74,.8) !important}
[data-wk="callbtns"] button > span:first-child svg{stroke:#0E3138 !important}
[data-wk="callbtns"] button:nth-child(2) > span:first-child{background:#E2A73C !important;box-shadow:0 0 0 1px #fff,0 0 18px rgba(246,227,176,.6) !important}
[data-wk="callbtns"] button:nth-child(2) > span:first-child svg{stroke:#fff !important}
[data-wk="call"][data-video="0"] [data-wk="callbtns"] button > span:last-child{color:rgba(255,255,255,.65) !important}
`;

